use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};
const R:&str="/tmp/zopro-arithmetic-leaves";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn insert(file:&str,start:&str,anchor:&str,text:&str,patches:&mut Vec<Value>){let p=Path::new(R).join("candidate/crates/zopro-core/src").join(file);let mut s=fs::read_to_string(&p).unwrap();let begin=s.find(start).unwrap_or_else(||panic!("start {file}:{start}"));let pos=begin+s[begin..].find(anchor).unwrap_or_else(||panic!("anchor {file}:{anchor}"))+anchor.len();let content=format!("\n#[cfg(zopro_arithmetic_trace)] {text}\n");s.insert_str(pos,&content);fs::write(&p,s).unwrap();patches.push(json!({"file":file,"inserted":content}));}
fn main(){for file in ["lib.rs","msm.rs","msm_affine.rs","msm/g2_prefix.rs","msm_affine/fused_kh.rs","msm_affine/g2_phi.rs"]{fs::copy(Path::new("/tmp/zopro-pairing-clean/baseline/crates/zopro-core/src").join(file),Path::new(R).join("candidate/crates/zopro-core/src").join(file)).unwrap();}let mut p=Vec::new();insert("lib.rs","mod msm;","mod msm;","pub mod arithmetic_trace;",&mut p);
 for(file,function,kind,arg)in [("msm_affine.rs","fn merge_split_width<",1,"bases.len(),width"),("msm_affine/fused_kh.rs","pub(crate)fn fused(",2,"k.len(),h.len()"),("msm_affine/g2_phi.rs","fn hb_raw(",3,"bases.len(),bits")]{let entry=if kind==2{"root"}else{"kernel"};insert(file,function,"{",&format!("let _trace_kernel=crate::arithmetic_trace::{entry}({kind},{arg});"),&mut p);}
 insert("msm_affine.rs","pub(super) fn msm<C:","{","let _trace_query=crate::arithmetic_trace::root(6,bases.len(),core::mem::size_of::<C::Base>());",&mut p);
 insert("msm_affine.rs","pub(super) fn g2_query_exclusive(","{","let _trace_query=crate::arithmetic_trace::root(5,bases.len(),0);",&mut p);
 // Root IDs are captured as plain integers, never non-Send Scope guards.
 for(file,function,window_kind)in [("msm_affine.rs","fn merge_split_width<",10),("msm_affine/fused_kh.rs","pub(crate)fn fused(",11),("msm_affine/g2_phi.rs","fn hb_raw(",12)]{let path=Path::new(R).join("candidate/crates/zopro-core/src").join(file);let s=fs::read_to_string(&path).unwrap();let begin=s.find(function).unwrap();let pos=begin+s[begin..].find("let _trace_kernel=").unwrap();let end=pos+s[pos..].find(';').unwrap()+1;let mut s=s;let content="\n#[cfg(zopro_arithmetic_trace)] let trace_kernel_id=_trace_kernel.id();\n";s.insert_str(end,content);fs::write(path,s).unwrap();p.push(json!({"file":file,"inserted":content}));let anchor=if file.contains("fused_kh"){".map(|w|{"}else{".map(|w| {"};let guard=format!("let _trace_window=crate::arithmetic_trace::scope(trace_kernel_id,{window_kind},w,0,false);");insert(file,function,anchor,&guard,&mut p);insert(file,function,&guard,"let trace_window_id=_trace_window.id();",&mut p);}
 insert("msm_affine.rs","fn merge_split_width<",".map(|p| {","let _trace_part=crate::arithmetic_trace::scope(trace_window_id,13,p,0,false);",&mut p);
 // A top-window join may run on another worker: capture its window ID explicitly.
 {let file="msm_affine/fused_kh.rs";let path=Path::new(R).join("candidate/crates/zopro-core/src").join(file);let mut s=fs::read_to_string(&path).unwrap();for(component,expr)in [(0,"top_window::<G1Config,true>(k,sk,w,bits)"),(1,"top_window::<G1Config,true>(h,sh,w,bits)")]{let replacement=format!("{{\n#[cfg(zopro_arithmetic_trace)] let _trace_top=crate::arithmetic_trace::scope(trace_window_id,15,{component},0,false);\n{expr}\n}}");assert_eq!(s.matches(expr).count(),1);s=s.replacen(expr,&replacement,1);p.push(json!({"file":file,"old_expr":expr,"new_expr":replacement}));}fs::write(path,s).unwrap();}
 insert("msm_affine/g2_phi.rs","fn hb_raw(",".map(|part| {","let _trace_part=crate::arithmetic_trace::scope(trace_window_id,14,part,0,false);",&mut p);
 insert("msm_affine/g2_phi.rs","fn hb_raw(","short.par_iter_mut().for_each(|s| *s = phi_split(*s));","{let ready=crate::arithmetic_trace::scope(trace_kernel_id,4,0,0,false);drop(ready);}",&mut p);
 // Serial phases and arithmetic batches: none of these bodies spawns Rayon work.
 for(file,function,kind,args)in [("msm_affine.rs","fn fill_window_deferred<",20,"bases.len(),width"),("msm_affine/fused_kh.rs","fn feed(",21,"points.len(),w"),("msm.rs","fn stream_g1_impl<",30,"batch.len(),buckets.len()"),("msm/g2_prefix.rs","pub(super) fn apply<",31,"batch.len(),buckets.len()"),("msm.rs","fn reduce_layer<",32,"points.len(),counts.len()"),("msm.rs","fn invert_lanes(",41,"c.len(),0")]{insert(file,function,"{",&format!("let _trace_serial=crate::arithmetic_trace::serial({kind},{args});"),&mut p);}
 insert("msm.rs","fn direct_chain_inverse(","if complete && vector_inverse {","let _trace_inverse=crate::arithmetic_trace::serial(40,0,0);",&mut p);
 insert("msm_affine/g2_phi.rs","fn hb_window(","    let size = batch_size(bits).max(32);","let _trace_serial=crate::arithmetic_trace::serial(22,bases.len(),w);",&mut p);
 for(file,function,anchor,kind,args)in [("msm.rs","fn group_affine_impl<","|(points, scratch), (i, output)| {",23,"output.len(),i"),("msm.rs","pub(super) fn reduce_indexed_buckets<",".map(|(first, end)| {",24,"end-first,first"),("msm.rs","pub(super) fn weighted_affine<","|(tree, scratch), buckets| {",25,"buckets.len(),0"),("msm_affine.rs","fn merge_buckets<",".for_each(|(left, right)| {",26,"left.len(),0")]{insert(file,function,"{","let trace_parent=crate::arithmetic_trace::parent();",&mut p);insert(file,function,anchor,&format!("let _trace_tile=crate::arithmetic_trace::scope(trace_parent,{kind},{args},true);"),&mut p);}
 // Keep all original bytes; the fixture patch log is the inverse transformation.
 let mut counts=BTreeMap::new();for x in &p{*counts.entry(x["file"].as_str().unwrap()).or_insert(0)+=1;}save(Path::new(R).join("insertions.json"),&json!(p));save(Path::new(R).join("insertion-counts.json"),&json!(counts));println!("Inserted bounded arithmetic recorder hooks");}
